def restore_input(value, original):
    """Restore a read-only broadcast view without writing one location twice."""
    target, source = value, original
    for dim in range(value.ndim - 1, -1, -1):
        if target.shape[dim] > 1 and target.stride(dim) == 0:
            target = target.select(dim, 0)
            source = source.select(dim, 0)
    target.copy_(source)

